//! Parity between the VoxCPM2 anchor in `voxr_narrate` and the JavaScript
//! it ports: the designed voice, its slower takes and its preparation, a
//! designed voice reused from the cache, and a user's recording prepared
//! into the cache.
//!
//! The fixture (`tests/fixtures/narration_anchor_oracle.json`) is checked in
//! and was generated by `tests/tools/narration_oracle/take_anchor.mjs`,
//! which runs a patched copy of the skill's own `voxcpm` with the model call
//! stubbed: each call speaks a synthetic take, a tone of the length the case
//! names for the call's seed, built bit for bit as `common::signals` builds
//! it. Each case here places the same files in a fresh cache, runs
//! [`designed_anchor`] and [`copy_voice_beside`], or [`clone_file`], and
//! compares every model call in order, each pace measured, every line
//! printed, the Hi-Fi transcript, and every file left with the hash of its
//! bytes.

use std::path::{Path, PathBuf};

use serde::Deserialize;
use voxr_narrate::{
    AnchorSetup, CloneReference, Error, Result, SpeakRequest, SpeechEngine, Take, TakeKeyInput,
    TakeSpec, TakeStore, VoiceSource, anchor_key, clone_file, copy_voice_beside, designed_anchor,
    pcm16_wav, prepared_marker, prepared_reference_key, read_wav_file, take_file, take_key,
};

mod common;
use common::signals::{self, Op, hiss, noise, tone};
use common::{assert_oracle_current, load_json, num};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_anchor_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/take_anchor.mjs"
);

const RATE: u32 = 48000;

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Fixture {
    checkpoint: String,
    ref_id: String,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    name: String,
    script: String,
    voice: Option<String>,
    seed: f64,
    style: Option<String>,
    hifi: bool,
    reference: bool,
    held: Held,
    takes: Vec<TakeShape>,
    anchor_key: String,
    calls: Vec<Call>,
    paces: Vec<String>,
    messages: Vec<String>,
    hifi_text: Option<String>,
    files: Vec<Listed>,
}

#[derive(Debug, Deserialize)]
struct Held {
    anchor: bool,
    transcript: Option<String>,
    marker: bool,
    prepared: bool,
}

#[derive(Debug, Clone, Copy, Deserialize)]
struct TakeShape {
    len: usize,
    breath: bool,
}

/// One model call: the text as spoken, the prefix, the seed, the voice
/// kind, the design description, the Hi-Fi transcript, and the hash of the
/// samples a clone reads from its reference.
#[derive(Debug, Clone, PartialEq, Deserialize)]
struct Call {
    text: String,
    prefix: Option<String>,
    seed: f64,
    voice: String,
    design: Option<String>,
    transcript: Option<String>,
    reference: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Deserialize)]
struct Listed {
    path: String,
    bytes: String,
}

/// `takeSignal` in take_anchor.mjs: 0.1 s of floor noise, a 200 Hz tone of
/// `len` samples, split by a breath when asked, then 0.1 s of floor noise.
fn take_signal(len: usize, breath: bool, noise_seed: u32) -> Vec<f32> {
    let lead = 4800;
    let gap = if breath { 960 + 7200 + 960 } else { 0 };
    let n = lead + len + gap + lead;
    let mut ops: Vec<Op> = vec![noise(0, n, 0.00002, noise_seed)];
    if breath {
        let half = len / 2;
        ops.push(tone("200", lead, half, 0.3, 480, 480));
        ops.push(hiss(lead + half + 960, 7200, 0.009, 41, 480, 480));
        ops.push(tone("200", lead + half + gap, len - half, 0.3, 480, 480));
    } else {
        ops.push(tone("200", lead, len, 0.3, 480, 480));
    }
    signals::render(n, &ops)
}

/// `HELD_ANCHOR` in take_anchor.mjs: a designed voice already in the cache.
fn held_anchor() -> Vec<f32> {
    signals::render(
        24000,
        &[
            noise(0, 24000, 0.00002, 5),
            tone("150", 0, 24000, 0.3, 480, 480),
        ],
    )
}

/// `RECORDING` in take_anchor.mjs: a user's recording.
fn recording() -> Vec<f32> {
    signals::render(
        72000,
        &[
            noise(0, 72000, 0.00002, 3),
            tone("200", 0, 14400, 0.3, 480, 480),
            hiss(15360, 7200, 0.009, 43, 480, 480),
            tone("150", 23520, 48000, 0.3, 480, 480),
        ],
    )
}

/// A 32-bit float WAV of `x`, as the oracle's stub model writes its takes.
fn wav_f32(x: &[f32], rate: u32) -> Vec<u8> {
    let data = (x.len() * 4) as u32;
    let mut out = Vec::with_capacity(44 + x.len() * 4);
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&(36 + data).to_le_bytes());
    out.extend_from_slice(b"WAVEfmt ");
    out.extend_from_slice(&16u32.to_le_bytes());
    out.extend_from_slice(&3u16.to_le_bytes());
    out.extend_from_slice(&1u16.to_le_bytes());
    out.extend_from_slice(&rate.to_le_bytes());
    out.extend_from_slice(&(rate * 4).to_le_bytes());
    out.extend_from_slice(&4u16.to_le_bytes());
    out.extend_from_slice(&32u16.to_le_bytes());
    out.extend_from_slice(b"data");
    out.extend_from_slice(&data.to_le_bytes());
    for v in x {
        out.extend_from_slice(&v.to_le_bytes());
    }
    out
}

fn io(what: &str, path: &Path) -> impl FnOnce(std::io::Error) -> Error {
    let reason = format!("{what} {}", path.display());
    move |e| Error::File {
        reason: format!("{reason}: {e}"),
    }
}

/// Speaks the case's synthetic take for each seed, and records each call.
struct Engine<'a> {
    case: &'a Case,
    calls: Vec<Call>,
}

impl SpeechEngine for Engine<'_> {
    type Reference = ();

    fn speak(&mut self, request: &SpeakRequest<'_, ()>) -> Result<Take> {
        let (design, transcript, reference) = match request.voice {
            VoiceSource::Own { design } => (design, None, None),
            VoiceSource::Clone {
                reference: CloneReference::Samples { samples, .. },
                transcript,
            } => (None, transcript, Some(signals::fnv1a(samples))),
            VoiceSource::Clone { .. } => {
                return Err(Error::DataError {
                    reason: "the anchor clones from samples, never a handle".to_string(),
                });
            }
        };
        self.calls.push(Call {
            text: request.text.to_string(),
            prefix: request.prefix().map(str::to_string),
            seed: request.seed,
            voice: request.voice.kind().to_string(),
            design: design.map(str::to_string),
            transcript: transcript.map(str::to_string),
            reference,
        });
        let k = request.seed - self.case.seed;
        let shape = self
            .case
            .takes
            .get(k as usize)
            .filter(|_| k >= 0.0 && k.fract() == 0.0)
            .ok_or_else(|| Error::DataError {
                reason: format!("case {} has no take for seed offset {k}", self.case.name),
            })?;
        Ok(Take {
            samples: take_signal(shape.len, shape.breath, 101 + k as u32),
            rate: RATE,
        })
    }
}

/// Writes each take as the oracle's stub model does, at the file the
/// skill's `takeFile` names.
struct Store<'a> {
    cache: &'a Path,
    checkpoint: &'a str,
    case: &'a Case,
}

impl TakeStore for Store<'_> {
    fn has(&mut self, _spec: &TakeSpec) -> bool {
        false
    }

    fn load(&mut self, spec: &TakeSpec) -> Result<Take> {
        Err(Error::DataError {
            reason: format!("the anchor never loads a take, asked for {:?}", spec.text),
        })
    }

    fn save(&mut self, spec: &TakeSpec, take: &Take) -> Result<()> {
        let style = spec
            .delivery
            .as_deref()
            .or(self.case.style.as_deref())
            .unwrap_or("");
        let key = take_key(
            Some(self.checkpoint),
            self.case.voice.as_deref().unwrap_or(""),
            "",
            TakeKeyInput {
                anchor_key: Some(self.case.anchor_key.as_str()),
                style,
                text: &spec.text,
                seed: spec.seed,
                cfg: 1.6,
                steps: 16.0,
                hifi: self.case.hifi,
            },
        );
        let file = take_file(self.cache, &key);
        std::fs::write(&file, wav_f32(&take.samples, take.rate)).map_err(io("writing", &file))
    }
}

/// Every file under `root`, by its `/`-joined path from `root`, with the
/// FNV-1a hash of its bytes, sorted by path.
fn listing(root: &Path) -> Result<Vec<Listed>> {
    let mut out = Vec::new();
    let mut dirs: Vec<PathBuf> = vec![root.to_path_buf()];
    while let Some(dir) = dirs.pop() {
        for entry in std::fs::read_dir(&dir).map_err(io("listing", &dir))? {
            let path = entry.map_err(io("listing", &dir))?.path();
            if path.is_dir() {
                dirs.push(path);
                continue;
            }
            let rel = path.strip_prefix(root).map_err(|e| Error::DataError {
                reason: format!("{} is outside {}: {e}", path.display(), root.display()),
            })?;
            let parts: Vec<String> = rel
                .components()
                .map(|c| c.as_os_str().to_string_lossy().into_owned())
                .collect();
            let bytes = std::fs::read(&path).map_err(io("reading", &path))?;
            out.push(Listed {
                path: parts.join("/"),
                bytes: signals::fnv1a_bytes(&bytes),
            });
        }
    }
    out.sort_by(|a, b| a.path.cmp(&b.path));
    Ok(out)
}

/// Places the files the case holds before its run.
fn hold(case: &Case, fixture: &Fixture, dir: &Path, cache: &Path) -> Result<()> {
    let voice = cache.join(format!("voice-{}.wav", case.anchor_key));
    if case.held.anchor {
        std::fs::write(&voice, pcm16_wav(&held_anchor(), RATE)?).map_err(io("writing", &voice))?;
    }
    if let Some(text) = &case.held.transcript {
        let said = voice.with_extension("txt");
        std::fs::write(&said, text).map_err(io("writing", &said))?;
    }
    if case.reference {
        let rec = dir.join("ref.wav");
        let bytes = pcm16_wav(&recording(), RATE)?;
        std::fs::write(&rec, &bytes).map_err(io("writing", &rec))?;
        if case.held.marker {
            let marker = prepared_marker(cache, &voxr_narrate::content_hash(&bytes));
            let prepared = cache.join("prepared");
            std::fs::create_dir_all(&prepared).map_err(io("creating", &prepared))?;
            std::fs::write(&marker, b"").map_err(io("writing", &marker))?;
        }
        if case.held.prepared {
            let key =
                prepared_reference_key(Some(fixture.checkpoint.as_str()), "", &fixture.ref_id);
            let copy = cache.join(format!("ref-{key}.wav"));
            std::fs::write(&copy, pcm16_wav(&held_anchor(), RATE)?)
                .map_err(io("writing", &copy))?;
        }
    }
    Ok(())
}

/// Reads a recording as 48 kHz mono samples.
fn decode(path: &Path) -> Result<Vec<f32>> {
    let take = read_wav_file(path)?;
    if take.rate != RATE {
        return Err(Error::DataError {
            reason: format!("{} is at {} Hz, not {RATE}", path.display(), take.rate),
        });
    }
    Ok(take.samples)
}

fn run(case: &Case, fixture: &Fixture) -> Result<()> {
    let name = &case.name;
    let tmp = tempfile::tempdir().map_err(|e| Error::File {
        reason: format!("creating a temporary directory: {e}"),
    })?;
    let dir = tmp.path();
    let cache = dir.join("cache");
    std::fs::create_dir_all(&cache).map_err(io("creating", &cache))?;
    let voice = case.voice.as_deref().unwrap_or("");
    assert_eq!(
        anchor_key(Some(fixture.checkpoint.as_str()), voice, case.seed, None),
        case.anchor_key,
        "anchor key, case {name}"
    );
    hold(case, fixture, dir, &cache)?;

    let mut engine = Engine {
        case,
        calls: Vec::new(),
    };
    let mut log = Vec::new();
    let mut paces = Vec::new();
    let mut hifi_text = None;
    if case.reference {
        let key = prepared_reference_key(Some(fixture.checkpoint.as_str()), voice, &fixture.ref_id);
        clone_file(&cache, &key, &dir.join("ref.wav"), &mut decode)?;
    } else {
        let mut store = Store {
            cache: &cache,
            checkpoint: &fixture.checkpoint,
            case,
        };
        let setup = AnchorSetup {
            cache_dir: &cache,
            key: &case.anchor_key,
            voice: case.voice.as_deref(),
            style: case.style.as_deref(),
            seed: case.seed,
            cfg: 1.6,
            steps: 16,
            hifi: case.hifi,
        };
        let anchor = designed_anchor(&case.script, &setup, &mut engine, &mut store, &mut log)?;
        copy_voice_beside(&anchor.file, &dir.join("out.wav"))?;
        if let Some(designed) = &anchor.designed {
            paces.clone_from(&designed.paces);
        }
        hifi_text = anchor.transcript;
    }

    assert_eq!(engine.calls, case.calls, "calls, case {name}");
    let want: Vec<f64> = case.paces.iter().map(|p| num(p)).collect();
    assert_eq!(paces, want, "paces, case {name}");
    let messages: Vec<String> = log.iter().filter_map(|s| s.message()).collect();
    assert_eq!(messages, case.messages, "messages, case {name}");
    assert_eq!(hifi_text, case.hifi_text, "Hi-Fi transcript, case {name}");
    assert_eq!(listing(dir)?, case.files, "files, case {name}");
    Ok(())
}

#[test]
fn matches_javascript_on_every_case() -> Result<()> {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");
    for case in &fixture.cases {
        run(case, &fixture)?;
    }
    Ok(())
}

#[test]
fn oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}
